// Paper (paper.college) design tokens + Material 3 theme.
//
// Drop-in for lib/theme/paper_tokens.dart. Pure Dart, depends only on
// package:flutter/material.dart. Generated by hand from
// design/tokens/paper-tokens.json, which is mapped 1:1 from the RPR web app
// (tailwind.config.ts + src/app/globals.css). Keep the two files in lockstep.
//
// v2 (web parity): every value equals what paper.college renders. The web
// is DARK-ONLY (layout.tsx server-renders <html class="dark">), so the app
// is dark-only too: [PaperColors.light] and [PaperTheme.light] are kept only
// as aliases of the dark values so existing call sites compile; remove them
// together with the theme toggle. Exact web colours by Tailwind name are in
// [PaperWeb]; the full mapping is design/web-parity/tokens.md.
//
// Requires Flutter >= 3.35 (uses AppBarThemeData / InputDecorationThemeData /
// CardThemeData / DialogThemeData and WidgetStateProperty).
//
// Usage:
//   MaterialApp(
//     theme: PaperTheme.dark(),
//     themeMode: ThemeMode.dark,
//   );
//   final colors = Theme.of(context).extension<PaperColors>()!;
//   final hl = Theme.of(context).extension<PaperHighlightColors>()!;

import 'package:flutter/material.dart';

// ---------------------------------------------------------------------------
// Colors
// ---------------------------------------------------------------------------

/// Semantic app colors. Light/dark pairs live in [PaperColors.light] and
/// [PaperColors.dark]. Brand rule: one indigo accent, everything else
/// hue-free neutral gray.
@immutable
class PaperColors extends ThemeExtension<PaperColors> {
  const PaperColors({
    required this.background,
    required this.surface,
    required this.surfaceVariant,
    required this.surfaceRaised,
    required this.pdfPage,
    required this.readerBackdrop,
    required this.primary,
    required this.onPrimary,
    required this.primaryHover,
    required this.primarySoft,
    required this.onPrimarySoft,
    required this.secondary,
    required this.onSecondary,
    required this.textPrimary,
    required this.textSecondary,
    required this.textMuted,
    required this.textDisabled,
    required this.border,
    required this.divider,
    required this.outline,
    required this.outlineVariant,
    required this.focusRing,
    required this.focusRingOnPaper,
    required this.scrim,
    required this.inverseSurface,
    required this.onInverseSurface,
    required this.inversePrimary,
    required this.success,
    required this.successSurface,
    required this.warning,
    required this.warningSurface,
    required this.error,
    required this.onError,
    required this.errorSurface,
    required this.errorBorder,
    required this.onErrorSurface,
    required this.info,
    required this.infoSurface,
    required this.statusOnline,
    required this.statusOffline,
    required this.statusSyncing,
    required this.statusSyncPending,
    required this.statusSynced,
    required this.statusSyncError,
    required this.selection,
    required this.cursor,
    required this.selectionHandle,
  });

  /// App canvas (web --background).
  final Color background;

  /// Cards, panels, sheets, dialogs.
  final Color surface;

  /// Hover fills, sidebar, chips.
  final Color surfaceVariant;

  /// Popovers and menus. The web draws them gray-900 + border + shadow,
  /// i.e. the same fill as [surface].
  final Color surfaceRaised;

  /// PDF page fill: white in BOTH themes (web parity).
  final Color pdfPage;

  /// Area around the PDF pages.
  final Color readerBackdrop;

  final Color primary;
  final Color onPrimary;
  final Color primaryHover;
  final Color primarySoft;
  final Color onPrimarySoft;
  final Color secondary;
  final Color onSecondary;

  final Color textPrimary;
  final Color textSecondary;

  /// Light: only on [background]/[surface] (4.54:1 / 4.74:1).
  final Color textMuted;
  final Color textDisabled;

  /// Decorative card/panel edge.
  final Color border;
  final Color divider;

  /// Control boundary: inputs, secondary buttons (web dark:border-gray-700).
  /// Web parity, NOT 3:1 (1.73:1 on [surface]); see tokens.md.
  final Color outline;

  /// Stronger neutral edge: HUD pills, hover rings (web gray-600).
  final Color outlineVariant;

  /// Focus ring on app chrome.
  final Color focusRing;

  /// Focus ring on the white PDF page: pinned indigo-600 in both themes.
  final Color focusRingOnPaper;

  final Color scrim;
  final Color inverseSurface;
  final Color onInverseSurface;
  final Color inversePrimary;

  final Color success;
  final Color successSurface;
  final Color warning;
  final Color warningSurface;
  final Color error;
  final Color onError;
  final Color errorSurface;
  final Color errorBorder;
  final Color onErrorSurface;
  final Color info;
  final Color infoSurface;

  final Color statusOnline;

  /// Neutral, NOT an error: reading works offline.
  final Color statusOffline;
  final Color statusSyncing;

  /// Local edits queued for sync.
  final Color statusSyncPending;
  final Color statusSynced;
  final Color statusSyncError;

  /// Text selection over the white PDF page (web .textLayer ::selection,
  /// indigo-600 @ 30%).
  final Color selection;
  final Color cursor;
  final Color selectionHandle;

  /// The web has no light theme. Alias of [dark], kept so existing call
  /// sites compile; delete with the theme toggle.
