    Color? readerBackdrop,
    Color? primary,
    Color? onPrimary,
    Color? primaryHover,
    Color? primarySoft,
    Color? onPrimarySoft,
    Color? secondary,
    Color? onSecondary,
    Color? textPrimary,
    Color? textSecondary,
    Color? textMuted,
    Color? textDisabled,
    Color? border,
