  @override
  PaperColors lerp(ThemeExtension<PaperColors>? other, double t) {
    if (other is! PaperColors) return this;
    Color l(Color a, Color b) => Color.lerp(a, b, t)!;
    return PaperColors(
      background: l(background, other.background),
      surface: l(surface, other.surface),
      surfaceVariant: l(surfaceVariant, other.surfaceVariant),
      surfaceRaised: l(surfaceRaised, other.surfaceRaised),
      pdfPage: l(pdfPage, other.pdfPage),
      readerBackdrop: l(readerBackdrop, other.readerBackdrop),
      primary: l(primary, other.primary),
      onPrimary: l(onPrimary, other.onPrimary),
      primaryHover: l(primaryHover, other.primaryHover),
      primarySoft: l(primarySoft, other.primarySoft),
      onPrimarySoft: l(onPrimarySoft, other.onPrimarySoft),
      secondary: l(secondary, other.secondary),
      onSecondary: l(onSecondary, other.onSecondary),
      textPrimary: l(textPrimary, other.textPrimary),
      textSecondary: l(textSecondary, other.textSecondary),
      textMuted: l(textMuted, other.textMuted),
      textDisabled: l(textDisabled, other.textDisabled),
      border: l(border, other.border),
      divider: l(divider, other.divider),
      outline: l(outline, other.outline),
      outlineVariant: l(outlineVariant, other.outlineVariant),
      focusRing: l(focusRing, other.focusRing),
      focusRingOnPaper: l(focusRingOnPaper, other.focusRingOnPaper),
      scrim: l(scrim, other.scrim),
      inverseSurface: l(inverseSurface, other.inverseSurface),
      onInverseSurface: l(onInverseSurface, other.onInverseSurface),
      inversePrimary: l(inversePrimary, other.inversePrimary),
      success: l(success, other.success),
      successSurface: l(successSurface, other.successSurface),
      warning: l(warning, other.warning),
      warningSurface: l(warningSurface, other.warningSurface),
      error: l(error, other.error),
      onError: l(onError, other.onError),
      errorSurface: l(errorSurface, other.errorSurface),
      errorBorder: l(errorBorder, other.errorBorder),
      onErrorSurface: l(onErrorSurface, other.onErrorSurface),
      info: l(info, other.info),
      infoSurface: l(infoSurface, other.infoSurface),
      statusOnline: l(statusOnline, other.statusOnline),
      statusOffline: l(statusOffline, other.statusOffline),
      statusSyncing: l(statusSyncing, other.statusSyncing),
      statusSyncPending: l(statusSyncPending, other.statusSyncPending),
      statusSynced: l(statusSynced, other.statusSynced),
      statusSyncError: l(statusSyncError, other.statusSyncError),
      selection: l(selection, other.selection),
      cursor: l(cursor, other.cursor),
      selectionHandle: l(selectionHandle, other.selectionHandle),
    );
  }
}

/// Every colour the in-scope web components paint, by Tailwind / CSS-var
/// name, resolved for the web's dark-only theme. Use these when a spec in
/// design/web-parity cites a Tailwind class (e.g. `dark:bg-gray-800` ->
/// [PaperWeb.gray800]). Opacity variants are pre-composited where the web
/// always paints them over a known surface; see tokens.md for the table.
abstract final class PaperWeb {
  // Neutral ramp (tailwind.config.ts overrides gray with hue-free R=G=B).
  static const Color gray50 = Color(0xFFFAFAFA);
  static const Color gray100 = Color(0xFFF5F5F5);
  static const Color gray200 = Color(0xFFE5E5E5);
  static const Color gray300 = Color(0xFFD4D4D4);
  static const Color gray400 = Color(0xFFA3A3A3);
  static const Color gray500 = Color(0xFF737373);
  static const Color gray600 = Color(0xFF525252);
  static const Color gray700 = Color(0xFF404040);
  static const Color gray800 = Color(0xFF262626);
  static const Color gray900 = Color(0xFF171717);
  static const Color gray950 = Color(0xFF0A0A0A);
  static const Color white = Color(0xFFFFFFFF);
  static const Color black = Color(0xFF000000);

  // CSS variables (.dark block of globals.css).
  static const Color background = gray950; // --background
  static const Color foreground = gray100; // --foreground
  static const Color accent = Color(0xFF818CF8); // --accent (indigo-400)
  static const Color accentHover = Color(0xFFA5B4FC); // --accent-hover
  static const Color accentSoft = Color(0xFF1E1B4B); // --accent-soft
  static const Color accentInk = Color(0xFFC7D2FE); // --accent-ink
  static const Color markFocusRing = Color(0xFF4F46E5); // --mark-focus-ring
  static const Color indigo950 = Color(0xFF1E1B4B); // dark:text-indigo-950

  // Status hues used by the components (dark: variants).
  static const Color red200 = Color(0xFFFECACA);
  static const Color red300 = Color(0xFFFCA5A5);
  static const Color red400 = Color(0xFFF87171);
  static const Color red500 = Color(0xFFEF4444);
  static const Color red900 = Color(0xFF7F1D1D);
  static const Color red950 = Color(0xFF450A0A);
  static const Color green400 = Color(0xFF4ADE80);
  static const Color amber400 = Color(0xFFFBBF24);

  // Opacity variants, composited over the surface they sit on.
  /// `dark:bg-gray-800/50` over gray-900 (table expanded row / hover).
  static const Color gray800Half = Color(0xFF1F1F1F);

  /// `dark:bg-gray-900/90` (toast) over gray-950.
  static const Color gray900Toast = Color(0xFF161616);

  /// `dark:hover:bg-yellow-900/40` (Highlight button hover) over gray-900.
  static const Color yellow900Hover = Color(0xFF3B2715);

  /// `dark:ring-white/10` (avatar / thumbnail hairline).
  static const Color white10 = Color(0x1AFFFFFF);

  /// `bg-white/5`-style translucent fills are not used in scope; text over
  /// thumbnails uses `from-gray-950/90 via-gray-950/75 to-transparent`.
  static const Color scrimGradientFrom = Color(0xE60A0A0A);
  static const Color scrimGradientVia = Color(0xBF0A0A0A);

  /// Dialog backdrop `dark:bg-[rgba(10,10,10,0.60)]`.
  static const Color dialogBackdrop = Color(0x990A0A0A);

  /// PDF text-layer selection (indigo-600 @ 30%).
  static const Color pdfSelection = Color(0x4D4F46E5);
}

// ---------------------------------------------------------------------------
// Highlights + reader marks
// ---------------------------------------------------------------------------

/// User highlight hues. Same recipe as the web's amber user highlight:
/// wash = Tailwind-400, reveal = 500, ring = 600 (>= 3:1 on white).
enum PaperHighlightColor {
  yellow(Color(0xFFFBBF24), Color(0xFFF59E0B), Color(0xFFD97706), 'Yellow'),
  green(Color(0xFF4ADE80), Color(0xFF22C55E), Color(0xFF16A34A), 'Green'),
  blue(Color(0xFF60A5FA), Color(0xFF3B82F6), Color(0xFF2563EB), 'Blue'),
  pink(Color(0xFFF472B6), Color(0xFFEC4899), Color(0xFFDB2777), 'Pink'),
  purple(Color(0xFFA78BFA), Color(0xFF8B5CF6), Color(0xFF7C3AED), 'Purple'),
  orange(Color(0xFFFB923C), Color(0xFFF97316), Color(0xFFEA580C), 'Orange');

  const PaperHighlightColor(this.wash, this.reveal, this.ring, this.label);

  /// Opaque base hue; apply the paper's alpha (see [PaperHighlightColors]).
  final Color wash;

  /// Opaque hover/pressed hue.
  final Color reveal;

  /// Opaque 1.5dp hover ring / swatch border.
  final Color ring;

  /// Default English label (localize via ARB in the app).
  final String label;

  static const PaperHighlightColor defaultColor = PaperHighlightColor.yellow;
}

/// Interaction state of a highlight / reader mark.
enum PaperMarkState { rest, hover, active }

/// AI reader-mark families: exact web values (globals.css).
enum PaperReaderMark {
  term(
    Color(0xFF60A5FA),
    Color(0x8C3B82F6),
    Color(0xAD3B82F6),
    Color(0xFF2563EB),
  ),
  citation(
    Color(0xFF818CF8),
    Color(0x8C6366F1),
    Color(0xAD6366F1),
    Color(0xFF4F46E5),
  ),
  appendix(
    Color(0xFF2DD4BF),
    Color(0x8C14B8A6),
    Color(0xAD14B8A6),
    Color(0xFF0D9488),
  ),
  mention(
    Color(0xFFA3A3A3),
    Color(0x8C737373),
    Color(0xAD737373),
    Color(0xFF525252),
  );

  const PaperReaderMark(this.wash, this.full, this.active, this.ring);

  /// Opaque rest-wash base; paint at [restAlpha] with multiply.
  final Color wash;

  /// Hover/focus fill (500 @ 0.55).
  final Color full;

  /// Pressed fill (500 @ 0.68).
  final Color active;

  /// Opaque 1.5dp hover ring.
  final Color ring;

  /// Web --*-wash-opacity.
  static const double restAlpha = 0.10;
}

/// How highlights paint for a given page appearance. The PDF page is white in
/// both app themes, so both themes register [whitePaper]; use [darkPaper]
/// only for an inverted "night paper" reader mode.
///
/// Paint same-colored overlapping rects in ONE layer (saveLayer / single
/// Opacity) with opaque [PaperHighlightColor.wash] and apply the alpha once,
/// so overlaps never darken (web no-stacking contract).
@immutable
class PaperHighlightColors extends ThemeExtension<PaperHighlightColors> {
  const PaperHighlightColors({
    required this.restAlpha,
    required this.hoverAlpha,
    required this.activeAlpha,
    required this.stylusInkAlpha,
    required this.blendMode,
    required this.pending,
  });

  final double restAlpha;
  final double hoverAlpha;
  final double activeAlpha;

  /// Pen-highlighter stroke alpha.
  final double stylusInkAlpha;

  /// [BlendMode.multiply] on white paper (glyphs stay dark);
  /// [BlendMode.srcOver] on dark paper (multiply would go black).
  final BlendMode blendMode;

  /// Just-created selection awaiting an action (web --highlight-mark-pending).
  final Color pending;

  static const double cornerRadius = 2;
  static const double hoverRingWidth = 1.5;
  static const double focusRingWidth = 2;
  static const double hoverScale = 1.02;

  static const PaperHighlightColors whitePaper = PaperHighlightColors(
    // Web --highlight-wash-opacity (rest wash, multiply on white paper).
    restAlpha: 0.10,
    hoverAlpha: 0.55,
    activeAlpha: 0.68,
    stylusInkAlpha: 0.45,
    blendMode: BlendMode.multiply,
    pending: Color(0x66FBBF24),
  );

  static const PaperHighlightColors darkPaper = PaperHighlightColors(
    restAlpha: 0.32,
    hoverAlpha: 0.45,
    activeAlpha: 0.55,
    stylusInkAlpha: 0.36,
    blendMode: BlendMode.srcOver,
    pending: Color(0x52FBBF24),
  );

  /// Alpha for [state].
  double alphaFor(PaperMarkState state) => switch (state) {
    PaperMarkState.rest => restAlpha,
    PaperMarkState.hover => hoverAlpha,
    PaperMarkState.active => activeAlpha,
  };

  /// Ready-to-paint fill for a single (non-overlapping) rect.
  Color fill(
    PaperHighlightColor color, [
    PaperMarkState state = PaperMarkState.rest,
  ]) {
    final Color base = state == PaperMarkState.rest ? color.wash : color.reveal;
    return base.withValues(alpha: alphaFor(state));
  }

  /// Fill for stylus highlighter strokes.
  Color ink(PaperHighlightColor color) =>
      color.wash.withValues(alpha: stylusInkAlpha);

  @override
  PaperHighlightColors copyWith({
    double? restAlpha,
    double? hoverAlpha,
    double? activeAlpha,
    double? stylusInkAlpha,
    BlendMode? blendMode,
    Color? pending,
  }) {
    return PaperHighlightColors(
      restAlpha: restAlpha ?? this.restAlpha,
      hoverAlpha: hoverAlpha ?? this.hoverAlpha,
      activeAlpha: activeAlpha ?? this.activeAlpha,
      stylusInkAlpha: stylusInkAlpha ?? this.stylusInkAlpha,
      blendMode: blendMode ?? this.blendMode,
      pending: pending ?? this.pending,
    );
  }

  @override
  PaperHighlightColors lerp(
    ThemeExtension<PaperHighlightColors>? other,
    double t,
  ) {
    if (other is! PaperHighlightColors) return this;
    double d(double a, double b) => a + (b - a) * t;
    return PaperHighlightColors(
      restAlpha: d(restAlpha, other.restAlpha),
      hoverAlpha: d(hoverAlpha, other.hoverAlpha),
      activeAlpha: d(activeAlpha, other.activeAlpha),
      stylusInkAlpha: d(stylusInkAlpha, other.stylusInkAlpha),
      blendMode: t < 0.5 ? blendMode : other.blendMode,
      pending: Color.lerp(pending, other.pending, t)!,
    );
  }
}

// ---------------------------------------------------------------------------
// Spacing, radii, elevation, sizes
// ---------------------------------------------------------------------------

/// 4dp grid.
abstract final class PaperSpacing {
  static const double none = 0;

  /// Hairline insets only (focus ring offset, mark padding).
  static const double xxs = 2;
  static const double xs = 4;
  static const double sm = 8;
  static const double md = 12;
  static const double lg = 16;
  static const double xl = 24;
  static const double xxl = 32;
  static const double xxxl = 48;
  static const double huge = 64;

  static const double panePadding = 16;

  /// Tailwind spacing unit: `p-N` / `gap-N` / `w-N` = N * 4 logical px.
  static double tw(double n) => n * 4;

  // Tailwind steps used by the in-scope web components (N -> px).
  static const double tw0_5 = 2;
  static const double tw1 = 4;
  static const double tw1_5 = 6;
  static const double tw2 = 8;
  static const double tw2_5 = 10;
  static const double tw3 = 12;
  static const double tw4 = 16;
  static const double tw5 = 20;
  static const double tw6 = 24;
  static const double tw8 = 32;
  static const double tw10 = 40;
  static const double tw12 = 48;
  static const double tw16 = 64;
  static const double tw20 = 80;
  static const double tw24 = 96;

  /// Space between grid columns for a window class.
  static double gutter(PaperWindowClass windowClass) => switch (windowClass) {
    PaperWindowClass.compact => 8,
    PaperWindowClass.medium => 16,
    PaperWindowClass.expanded => 24,
    PaperWindowClass.large => 24,
    PaperWindowClass.extraLarge => 24,
  };

  /// Outer page margin (left/right) for a window class.
  static double margin(PaperWindowClass windowClass) => switch (windowClass) {
    PaperWindowClass.compact => 16,
    PaperWindowClass.medium => 24,
    PaperWindowClass.expanded => 24,
    PaperWindowClass.large => 32,
    PaperWindowClass.extraLarge => 40,
  };

  /// Layout grid column count for a window class.
  static int columns(PaperWindowClass windowClass) => switch (windowClass) {
    PaperWindowClass.compact => 4,
    PaperWindowClass.medium => 8,
    _ => 12,
  };
}

