      color: Color(0x1A000000),
      offset: Offset(0, 8),
      blurRadius: 10,
      spreadRadius: -6,
    ),
  ];

  /// Tailwind `shadow-2xl`: 0 25px 50px -12px rgb(0 0 0 / .25).
