// ---------------------------------------------------------------------------
// Motion
// ---------------------------------------------------------------------------

/// Web parity durations/curves. Animate opacity/transform only.
abstract final class PaperMotion {
  /// Press/active deepen, toggles.
  static const Duration instant = Duration(milliseconds: 80);

  /// Hover/focus reveal, tooltips.
  static const Duration fast = Duration(milliseconds: 150);

  /// Settle/out, color changes.
  static const Duration base = Duration(milliseconds: 200);

  /// Scrims, side panel, sheets.
  static const Duration slow = Duration(milliseconds: 300);

  /// Route transitions.
  static const Duration page = Duration(milliseconds: 300);

  /// One-off hero moves; never on scroll paths.
  static const Duration emphasis = Duration(milliseconds: 420);

  /// Pointer hover-in anti-strobe delay (not keyboard focus).
  static const Duration hoverDelay = Duration(milliseconds: 40);

  /// In-place changes, departures (web --mark-ease-settle).
  static const Cubic standard = Cubic(0.4, 0.0, 0.2, 1.0);

  /// Arrivals/reveals (web --mark-ease-reveal).
  static const Cubic decelerate = Cubic(0.0, 0.0, 0.2, 1.0);

  /// Exits off-screen.
  static const Cubic accelerate = Cubic(0.4, 0.0, 1.0, 1.0);
  static const Curve linear = Curves.linear;

  /// Tailwind `transition-colors` / `transition-transform` default: 150ms
  /// [standard]. Every hover/press colour change on the web uses this.
  static const Duration colors = fast;

  /// Focus-lock backdrop fade.
  static const Duration backdrop = Duration(milliseconds: 300);

  /// `animate-spin` (spinners): one turn per second, linear.
  static const Duration spin = Duration(seconds: 1);

  /// `animate-pulse` (skeletons): 2s, opacity 1 -> .5 -> 1.
  static const Duration pulse = Duration(seconds: 2);
  static const Cubic pulseCurve = Cubic(0.4, 0.0, 0.6, 1.0);

  /// `.animate-progress-indeterminate`: 1.2s ease-in-out, translateX -100% -> 300%.
  static const Duration progressIndeterminate = Duration(milliseconds: 1200);

  static const double markHoverScale = 1.02;
  static const double termHoverScale = 1.04;
  static const double pressScale = 0.98;

  /// Returns [Duration.zero] when the OS asks to reduce motion, else
  /// [duration]. Use [fade] for opacity-only changes that should still run.
  static Duration of(BuildContext context, Duration duration) =>
      MediaQuery.disableAnimationsOf(context) ? Duration.zero : duration;

  /// Opacity fades under reduced motion are capped at [fast].
  static Duration fade(BuildContext context, Duration duration) =>
      MediaQuery.disableAnimationsOf(context) && duration > fast
      ? fast
      : duration;
}

